+                    assertBusy(() -> assertTrue(cancellableTask.isCancelled()));
+                    channel.sendResponse(new TaskCancelledException("task cancelled"));
+                });
+
+            childTransportService.start();
+            childTransportService.acceptIncomingRequests();
